def build3(Yp=185., L=57., Rw=199., off=8., dead=2., dfol=2., K=2.0, K2=3.0,
           vx={1:1.,2:1.5}, vy={1:1.,2:2.,3:3.,4:4.}, up_mode='follow', upoff=0.0):
    W1=np.zeros((128,64),np.float32); b1=np.zeros(64,np.float32)
    W2=np.zeros((64,64),np.float32); b2=np.zeros(64,np.float32)
    W3=np.zeros((64,18),np.float32); b3=np.zeros(18,np.float32)
    n1=[0]
    def thr(byte, c, Kt=4.0):
        j=n1[0]; n1[0]+=1
        W1[byte,j]=255*Kt; b1[j]=-Kt*c; return j
    def lin(coefs, const):
        j=n1[0]; n1[0]+=1
        for byte,c in coefs.items(): W1[byte,j]+=255*K*c
        b1[j]=K*const; return j
    BX,BY,P,DY,DX=99,101,72,103,105
    dy_ge={c:thr(DY,c) for c in [0.5,1.5,2.5,3.5,127.5]}
    dx_ge={c:thr(DX,c) for c in [0.5,1.5,127.5,254.5]}
    dygate={1:[(dy_ge[0.5],1),(dy_ge[1.5],-1)],2:[(dy_ge[1.5],1),(dy_ge[2.5],-1)],
            3:[(dy_ge[2.5],1),(dy_ge[3.5],-1)],4:[(dy_ge[3.5],1),(dy_ge[127.5],-1)]}
    dxgate={0:[(dx_ge[0.5],-1)],1:[(dx_ge[0.5],1),(dx_ge[1.5],-1)],2:[(dx_ge[1.5],1),(dx_ge[127.5],-1)],
            -1:[(dx_ge[254.5],1)],-2:[(dx_ge[127.5],1),(dx_ge[254.5],-1)]}
    n2=[0]
    def AND(lits, action):
        j=n2[0]; n2[0]+=1
        for i,sg in lits: W2[i,j]+=sg*K2
        b2[j]=-K2*(len(lits)-1)
        W3[j,action]+=1; b3[action]+=1
        return j
    RIGHT,LEFT=11,12
    sl=lambda dx,dy: (0.0 if dx==0 else float(-np.sign(dx)*vx[abs(dx)]/vy[dy]))
    slopes=sorted(set(sl(dx,dy) for dx in [-2,-1,0,1,2] for dy in [1,2,3,4]))
    eu={}
    for s in slopes:
        base={BX:1.0,BY:-s,P:-1.0}; c0=s*Yp-off
        eu[s]=dict(dR=lin(base,c0-dead), dL=lin(base,c0+dead))
        if s!=0:
            W=Rw if s>0 else L
            refl={BX:-1.0,BY:s,P:-1.0}; c1=2*W-s*Yp-off
            eu[s]['rR']=lin(refl,c1-dead); eu[s]['rL']=lin(refl,c1+dead)
    for dx in [-2,-1,0,1,2]:
        for dy in [1,2,3,4]:
            s=sl(dx,dy); g=dxgate[dx]+dygate[dy]; e=eu[s]
            if s>0:
                AND(g+[(e['dR'],1),(e['rR'],1)],RIGHT)
                AND(g+[(e['dL'],-1)],LEFT); AND(g+[(e['rL'],-1)],LEFT)
            elif s<0:
                AND(g+[(e['dL'],-1),(e['rL'],-1)],LEFT)
                AND(g+[(e['dR'],1)],RIGHT); AND(g+[(e['rR'],1)],RIGHT)
            else:
                AND(g+[(e['dR'],1)],RIGHT); AND(g+[(e['dL'],-1)],LEFT)
    fR=lin({BX:1.0,P:-1.0},-off-upoff-dfol); fL=lin({BX:1.0,P:-1.0},-off-upoff+dfol)
    AND([(dy_ge[127.5],1),(fR,1)],RIGHT); AND([(dy_ge[127.5],1),(fL,-1)],LEFT)
    b3[1]+=1.0
    assert n1[0]<=64 and n2[0]<=64, (n1[0],n2[0])
    return dict(W1=W1,b1=b1,W2=W2,b2=b2,W3=W3,b3=b3)
