def build4(vx={1:1.,2:1.5}, vy={1:1.,2:2.,3:3.,4:4.}, merge=0.05, **kw):
    raw={(dx,dy):(0.0 if dx==0 else float(-np.sign(dx)*vx[abs(dx)]/vy[dy])) for dx in [-2,-1,0,1,2] for dy in [1,2,3,4]}
    # greedy merge of close slopes
    canon=[]
    for v in sorted(set(raw.values()),key=abs):
        m=[c for c in canon if abs(c-v)<=merge*max(1,abs(v)) and np.sign(c)==np.sign(v)]
        if not m: canon.append(v)
    def snap(v): return min(canon,key=lambda c:abs(c-v)+ (100 if np.sign(c)!=np.sign(v) else 0))
    table={k:snap(v) for k,v in raw.items()}
    return table
